import{_ as r,o as t,c as i,a6 as e}from"./chunks/framework.DfoD60a6.js";const u=JSON.parse('{"title":"同步、死結與記憶體名詞","description":"","frontmatter":{"prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"theory/systems-glossary.md","filePath":"theory/systems-glossary.md"}'),a={name:"theory/systems-glossary.md"};function n(s,o,l,g,c,h){return t(),i("div",null,[...o[0]||(o[0]=[e('<h1 id="同步、死結與記憶體名詞" tabindex="-1">同步、死結與記憶體名詞 <a class="header-anchor" href="#同步、死結與記憶體名詞" aria-label="Permalink to &quot;同步、死結與記憶體名詞&quot;">​</a></h1><p>集中查找同步、死結與主記憶體名詞。各章正文提供實際使用時的條件與程式碼。</p><p>對照 WUWAOS 章節：<a href="./../spec/06-synchronization-tools.html">06 · 同步工具怎麼做</a> · <a href="./../spec/08-virtual-memory.html">08 · 頁面、虛擬記憶體與 COW</a></p><p>教材：恐龍書第 10 版 第 6、8、9 章。 <a href="https://github.com/johnson931128/WUWAOS/blob/main/notes/%E5%90%8D%E8%A9%9E%E7%99%BE%E7%A7%91.md" target="_blank" rel="noreferrer">原始課堂筆記</a></p><h2 id="ch6" tabindex="-1">ch6 <a class="header-anchor" href="#ch6" aria-label="Permalink to &quot;ch6&quot;">​</a></h2><h4 id="一、-核心概念與併發問題-core-concepts-problems" tabindex="-1">一、 核心概念與併發問題 (Core Concepts &amp; Problems) <a class="header-anchor" href="#一、-核心概念與併發問題-core-concepts-problems" aria-label="Permalink to &quot;一、 核心概念與併發問題 (Core Concepts &amp; Problems)&quot;">​</a></h4><ul><li><strong>Concurrent execution</strong>：並發執行</li><li><strong>Parallel execution</strong>：平行執行</li><li><strong>Race Condition</strong>：競態條件（多個實體同時存取共享資料，結果取決於執行的特定順序）</li><li><strong>Context Switch</strong>：內容交換</li><li><strong>Instruction Reordering</strong>：指令重排（現代硬體或編譯器為求效能而調換指令順序）</li><li><strong>Deadlock</strong>：死結（多個行程互相等待對方釋放資源，導致全體卡死）</li><li><strong>Starvation</strong>：飢餓（行程被無限期推遲，永遠拿不到資源）</li><li><strong>Busy waiting</strong>：忙碌等待（拿不到鎖時在 <code>while</code> 迴圈中不斷空轉浪費 CPU）</li><li><strong>Lock Contention</strong>：鎖競爭（包含 High contention 高競爭與 Low contention 低競爭）</li></ul><h4 id="二、-臨界區間與三項要求-critical-section-the-three-requirements" tabindex="-1">二、 臨界區間與三項要求 (Critical-Section &amp; The Three Requirements) <a class="header-anchor" href="#二、-臨界區間與三項要求-critical-section-the-three-requirements" aria-label="Permalink to &quot;二、 臨界區間與三項要求 (Critical-Section &amp; The Three Requirements)&quot;">​</a></h4><ul><li><strong>Critical Section</strong>：臨界區間（存取共享資料的危險程式碼區塊）</li><li><strong>Entry section / Exit section</strong>：進入區間（申請鎖）/ 離開區間（釋放鎖）</li><li><strong>Remainder section</strong>：剩餘區間（與共享資料無關的其他程式碼）</li><li><strong>Mutual exclusion</strong>：互斥（同一時間只能有一個行程進入臨界區間）</li><li><strong>Progress</strong>：進行（不想進去的人不能卡住想進去的人，避免死結）</li><li><strong>Bounded waiting</strong>：有限等待（排隊有上限，避免飢餓）</li></ul><h4 id="三、-硬體層級同步支援-hardware-support" tabindex="-1">三、 硬體層級同步支援 (Hardware Support) <a class="header-anchor" href="#三、-硬體層級同步支援-hardware-support" aria-label="Permalink to &quot;三、 硬體層級同步支援 (Hardware Support)&quot;">​</a></h4><ul><li><strong>Memory Model</strong>：記憶體模型（包含 Strongly ordered 強排序與 Weakly ordered 弱排序）</li><li><strong>Memory Barriers / Memory Fences</strong>：記憶體屏障 / 記憶體柵欄（防止指令重排的底層硬體指令）</li><li><strong>Atomic Operations</strong>：原子操作（不可分割、一氣呵成的硬體執行單元）</li><li><strong><code>test_and_set</code></strong>：測試與設定指令（硬體原子指令）</li><li><strong><code>compare_and_swap</code> (CAS)</strong>：比較與交換指令（硬體原子指令）</li><li><strong>Atomic Variables</strong>：原子變數（如 <code>atomic_int</code>，利用 CAS 實作的單一變數更新工具）</li><li><strong>Optimistic Locking</strong>：樂觀鎖（先運算再用 CAS 檢查有無衝突的無鎖設計）</li></ul><h4 id="四、-軟體高階同步工具-software-synchronization-tools" tabindex="-1">四、 軟體高階同步工具 (Software Synchronization Tools) <a class="header-anchor" href="#四、-軟體高階同步工具-software-synchronization-tools" aria-label="Permalink to &quot;四、 軟體高階同步工具 (Software Synchronization Tools)&quot;">​</a></h4><ul><li><strong>Mutex Lock</strong>：互斥鎖（Mutual exclusion 的縮寫） <ul><li><strong>acquire()：取得</strong></li><li><strong>release()：釋放</strong></li></ul></li><li><strong>Spinlock</strong>：自旋鎖（會產生忙碌等待的互斥鎖，適用於短暫時間的防護）</li><li><strong>Semaphore</strong>：號誌（包含 wait/P 操作與 signal/V 操作） <ul><li><code>wait()</code> (或稱 P 操作)：用來申請資源。它會先將號誌的資源數值減 1。如果減完後數值小於 0，代表資源已耗盡，該行程會立刻將自己加入等待名單，並呼叫 <code>sleep()</code> 強制休眠交出 CPU。</li><li><code>signal()</code> (或稱 V 操作)：用來釋放/歸還資源。它會將號誌的資源數值加 1。如果加完後數值依然小於等於 0，代表外面還有行程在苦苦排隊，系統會從等待名單中挑選一個幸運兒，並呼叫 <code>wakeup()</code> 將其喚醒準備執行。</li></ul></li><li><strong>Binary Semaphores</strong>：二元號誌（值為 0 或 1，常做為互斥鎖使用）</li><li><strong>Counting Semaphores</strong>：計數號誌（管控有限數量的實體資源）</li><li><strong>Monitor type</strong>：管程型別（將共享資料與同步機制封裝在一起的抽象資料型別 ADT）</li><li><strong>Condition Variables</strong>：條件變數（供行程在管程內暫時休眠退位的機制）</li><li><strong>Signal and wait / Signal and continue</strong>：管程中喚醒休眠行程後的兩種控制權移交流派</li></ul><h4 id="五、-經典同步問題-classic-problems-of-synchronization" tabindex="-1">五、 經典同步問題 (Classic Problems of Synchronization) <a class="header-anchor" href="#五、-經典同步問題-classic-problems-of-synchronization" aria-label="Permalink to &quot;五、 經典同步問題 (Classic Problems of Synchronization)&quot;">​</a></h4><ul><li><strong>The Bounded-Buffer Problem</strong>：有限緩衝區問題（即生產者－消費者問題 Producer-Consumer Problem） <ul><li>探討生產者與消費者共享一個固定大小緩衝區的同步情境；其核心在於利用號誌控管資源與互斥，確保生產者在緩衝區「客滿」時必定休眠等待、消費者在緩衝區「空虛」時暫停讀取，並嚴格保證任何時刻都只能有一個行程對緩衝區進行寫入或取出，以防資料互相覆蓋或讀取異常。</li></ul></li><li><strong>The Readers–Writers Problem</strong>：讀者－寫者問題（衍生出 Reader-Writer Locks 讀寫鎖） <ul><li>模擬多個行程並發存取共享資料庫的衝突與效能取捨；其核心防護原則是允許多個「讀者 (Readers)」同時讀取資料以最大化系統效能，但嚴格規定「寫者 (Writers)」在修改資料時必須擁有絕對的排他獨佔權 (Exclusive access)，禁止任何其他讀者或寫者同時闖入，藉此避免資料庫陷入混亂狀態。</li></ul></li><li><strong>The Dining-Philosophers Problem</strong>：哲學家就餐問題（探討資源分配與死結、循環等待 Circular Wait）</li></ul><h2 id="ch8" tabindex="-1">ch8 <a class="header-anchor" href="#ch8" aria-label="Permalink to &quot;ch8&quot;">​</a></h2><h4 id="一、-核心名詞與物理模型-core-terms-system-model" tabindex="-1">一、 核心名詞與物理模型 (Core Terms &amp; System Model) <a class="header-anchor" href="#一、-核心名詞與物理模型-core-terms-system-model" aria-label="Permalink to &quot;一、 核心名詞與物理模型 (Core Terms &amp; System Model)&quot;">​</a></h4><ul><li><strong>Resource types</strong>：資源類型（如 CPU、檔案、I/O 裝置、甚至是互斥鎖與號誌，皆被視為系統資源）</li><li><strong>Identical instances</strong>：相同的實例（同一資源類型下可互相替代的資源個體）</li><li><strong>Request / Use / Release</strong>：資源操作標準程序（申請、使用、釋放）</li><li><strong>Resource-Allocation Graph</strong>：資源分配圖（由執行緒頂點與資源頂點構成的視覺化圖形）</li><li><strong>Request Edge</strong>：申請邊（執行緒指向資源，代表等待中）</li><li><strong>Assignment Edge</strong>：分配邊（資源黑點指向執行緒，代表已握有該實例）</li></ul><h4 id="二、-死結特徵與四大必要條件-deadlock-characteristics" tabindex="-1">二、 死結特徵與四大必要條件 (Deadlock Characteristics) <a class="header-anchor" href="#二、-死結特徵與四大必要條件-deadlock-characteristics" aria-label="Permalink to &quot;二、 死結特徵與四大必要條件 (Deadlock Characteristics)&quot;">​</a></h4><ul><li><strong>Deadlock</strong>：死結（一組執行緒皆在等待同集合內其他執行緒才能觸發的釋放事件，導致系統卡死）</li><li><strong>Mutual Exclusion</strong>：互斥（資源具排他性，不可共享）</li><li><strong>Hold and Wait</strong>：持有並等待（執行緒握有部分資源，同時等待獲取別人手上的資源）</li><li><strong>No Preemption</strong>：不可剝奪（系統不可強行搶奪資源，需等執行緒自願釋放）</li><li><strong>Circular Wait</strong>：循環等待（形成完美的封閉等待環）</li></ul><h4 id="三、-死結處理四大流派-four-major-handling-strategies" tabindex="-1">三、 死結處理四大流派 (Four Major Handling Strategies) <a class="header-anchor" href="#三、-死結處理四大流派-four-major-handling-strategies" aria-label="Permalink to &quot;三、 死結處理四大流派 (Four Major Handling Strategies)&quot;">​</a></h4><ul><li><strong>Deadlock Prevention</strong>：死結預防（從物理或邏輯上制定嚴格規範，破壞四大必要條件之一，確保死結永不發生）</li><li><strong>Deadlock Avoidance</strong>：死結避免（要求執行緒預先宣告最大需求，每次分配前進行沙盤推演，避免進入不安全狀態）</li><li><strong>Deadlock Detection</strong>：死結偵測（允許死結發生，定期在背景尋找循環等待的證據）</li><li><strong>Recovery from Deadlock</strong>：死結復原（抓到死結後，透過殺死行程或剝奪資源來打破僵局）</li><li><strong>Ostrich Algorithm</strong>：鴕鳥演算法（假裝問題不存在，為包含 Linux/Windows 在內的多數現代 OS 採用的策略，將責任轉嫁給開發者）</li></ul><h4 id="四、-演算法與狀態判定-algorithms-state-evaluation" tabindex="-1">四、 演算法與狀態判定 (Algorithms &amp; State Evaluation) <a class="header-anchor" href="#四、-演算法與狀態判定-algorithms-state-evaluation" aria-label="Permalink to &quot;四、 演算法與狀態判定 (Algorithms &amp; State Evaluation)&quot;">​</a></h4><ul><li><strong>Safe State</strong>：安全狀態（存在一組安全排序，系統有絕對控制權保證所有人完工，絕對無死結）</li><li><strong>Unsafe State</strong>：不安全狀態（找不到安全排序，死結「有可能」發生，但非必然）</li><li><strong>Safe Sequence</strong>：安全排序（一組執行緒的排列順序，確保後續者的需求能被目前的閒置資源加前面執行緒歸還的資源所滿足）</li><li><strong>Total Ordering</strong>：全序排列（死結預防的實務作法：賦予資源整數編號，強制依遞增順序申請以破除循環等待）</li><li><strong>Banker&#39;s Algorithm</strong>：銀行家演算法（用於多重資源實例的死結避免演算法）</li><li><strong>Available / Max / Allocation / Need</strong>：銀行家演算法四大矩陣（可用資源、最大需求、已分配資源、尚需資源）</li><li><strong>Claim Edge</strong>：宣告邊（死結避免演算法中代表「未來可能需求」的虛線）</li><li><strong>Wait-for Graph</strong>：等待圖（刪除資源節點並合併邊緣，用於單一資源實例的死結偵測）</li></ul><h4 id="五、-復原機制與衍伸問題-recovery-mechanisms-issues" tabindex="-1">五、 復原機制與衍伸問題 (Recovery Mechanisms &amp; Issues) <a class="header-anchor" href="#五、-復原機制與衍伸問題-recovery-mechanisms-issues" aria-label="Permalink to &quot;五、 復原機制與衍伸問題 (Recovery Mechanisms &amp; Issues)&quot;">​</a></h4><ul><li><strong>Process / Thread Termination</strong>：行程終止（選擇全殺或一次殺一個來解除死結）</li><li><strong>Resource Preemption</strong>：資源剝奪（強行搶走某死結行程的資源分給別人）</li><li><strong>Selecting a Victim</strong>：挑選犧牲者（基於優先權、已用時間、牽連範圍等因素計算最小成本）</li><li><strong>Rollback / Total rollback</strong>：回滾 / 完全回滾（被剝奪資源的行程必須退回安全狀態或直接重頭執行）</li><li><strong>Starvation</strong>：飢餓（復原時若只看當下成本，弱勢行程可能永遠被當成肥羊剝奪資源而餓死，解法是將「被回滾次數」加入成本計算）</li><li><strong>Disjoint cycle</strong>：不相交循環（資源分配圖中完全獨立的多個死結圈，復原時每個圈都必須至少挑選一名犧牲者）</li></ul><h2 id="ch9" tabindex="-1">ch9 <a class="header-anchor" href="#ch9" aria-label="Permalink to &quot;ch9&quot;">​</a></h2><h4 id="一、-核心概念與硬體支援-core-concepts-hardware-support" tabindex="-1">一、 核心概念與硬體支援 (Core Concepts &amp; Hardware Support) <a class="header-anchor" href="#一、-核心概念與硬體支援-core-concepts-hardware-support" aria-label="Permalink to &quot;一、 核心概念與硬體支援 (Core Concepts &amp; Hardware Support)&quot;">​</a></h4><ul><li><strong>Virtual Memory vs. Physical Memory</strong>：虛擬記憶體與實體記憶體（行程看見的邏輯連續位址空間，與硬體真實的存放位置，兩者透過系統脫鉤）。</li><li><strong>MMU (Memory Management Unit)</strong>：記憶體管理單元（負責在底層將 CPU 產生的虛擬邏輯位址，動態翻譯成實體位址的硬體裝置）。</li><li><strong>Base register / Limit register</strong>：基底暫存器與極限暫存器（分別記錄行程合法的「最小實體位址」與「可存取範圍」，由硬體進行越界檢查以實現記憶體保護）。</li><li><strong>TLB (Translation Look-Aside Buffer)</strong>：轉譯後備緩衝區（內建於 CPU 管線的極速快取，儲存近期的位址映射，用以解決分頁表放在主記憶體所導致的「兩次存取」效能延遲）。</li><li><strong>PTBR (Page-table base register)</strong>：分頁表基底暫存器（指向存放於主記憶體中的分頁表起點）。</li><li><strong>ASID (Address-space identifier)</strong>：位址空間識別碼（TLB 條目中的行程身分證，允許 TLB 同時存放多個行程的快取而不必在內容交換時清空）。</li></ul><h4 id="二、-程式綁定與載入機制-binding-loading-mechanisms" tabindex="-1">二、 程式綁定與載入機制 (Binding &amp; Loading Mechanisms) <a class="header-anchor" href="#二、-程式綁定與載入機制-binding-loading-mechanisms" aria-label="Permalink to &quot;二、 程式綁定與載入機制 (Binding &amp; Loading Mechanisms)&quot;">​</a></h4><ul><li><strong>Address Binding</strong>：位址綁定（將程式碼中的邏輯位址轉換為實體位址的過程，可發生在編譯時期、載入時期或執行時期）。</li><li><strong>Absolute code / Relocatable code</strong>：絕對程式碼（編譯時寫死實體位址）與可重定位程式碼（寫成相對偏移量，可在記憶體中任意放置）。</li><li><strong>Dynamic Loading</strong>：動態載入（常式只有在真正被呼叫時才會載入記憶體，節省空間，不需 OS 特別支援）。</li><li><strong>Dynamic Linking / Shared Libraries</strong>：動態連結與共享函式庫（將連結推遲到執行時期，允許多個行程在實體記憶體中共用同一份函式庫副本，需 OS 支援）。</li></ul><h4 id="三、-連續記憶體配置與演算法-contiguous-allocation-algorithms" tabindex="-1">三、 連續記憶體配置與演算法 (Contiguous Allocation &amp; Algorithms) <a class="header-anchor" href="#三、-連續記憶體配置與演算法-contiguous-allocation-algorithms" aria-label="Permalink to &quot;三、 連續記憶體配置與演算法 (Contiguous Allocation &amp; Algorithms)&quot;">​</a></h4><ul><li><strong>Variable-partition scheme</strong>：變動分割機制（實體記憶體依行程需求動態切分大小，每個分割區恰好包含一個行程）。</li><li><strong>Hole</strong>：記憶體空洞（記憶體中連續的未分配可用空間）。</li><li><strong>First fit / Best fit / Worst fit</strong>：首次適應（找第一個夠大的）、最佳適應（找剛好夠大中最小的）、最差適應（找最大的空洞配置）。</li><li><strong>Buddy System</strong>：夥伴系統（將記憶體依 2 的次方進行對半切割與合併的演算法，釋放極快但內部碎裂嚴重）。</li><li><strong>Next fit (Roving Pointer)</strong>：下次適應（使用漫遊指標，從上次配置的位置繼續環狀尋找空洞，速度快但易切碎後段大空間）。</li></ul><h4 id="四、-記憶體碎裂現象與對策-fragmentation-solutions" tabindex="-1">四、 記憶體碎裂現象與對策 (Fragmentation &amp; Solutions) <a class="header-anchor" href="#四、-記憶體碎裂現象與對策-fragmentation-solutions" aria-label="Permalink to &quot;四、 記憶體碎裂現象與對策 (Fragmentation &amp; Solutions)&quot;">​</a></h4><ul><li><strong>External Fragmentation</strong>：外部碎裂（總剩餘空間足夠，但散落成不連續的小空洞導致無法配置）。</li><li><strong>Internal Fragmentation</strong>：內部碎裂（為配合固定區塊大小而多給的記憶體，浪費在分割區內部無法被回收）。</li><li><strong>50% Rule</strong>：50% 規則（統計指出外部碎裂極為嚴重，可能讓系統憑空損失三分之一的記憶體效能）。</li><li><strong>Compaction</strong>：緊緻化 / 記憶體壓縮（將記憶體內容推擠集中，把零碎空洞合併成大空洞的解法，僅限支援執行時期動態重定位的系統使用）。</li></ul><h4 id="五、-非連續記憶體配置-分段與分頁-segmentation-paging" tabindex="-1">五、 非連續記憶體配置：分段與分頁 (Segmentation &amp; Paging) <a class="header-anchor" href="#五、-非連續記憶體配置-分段與分頁-segmentation-paging" aria-label="Permalink to &quot;五、 非連續記憶體配置：分段與分頁 (Segmentation &amp; Paging)&quot;">​</a></h4><ul><li><strong>Segmentation</strong>：分段機制（支援使用者視角，將程式切為不同邏輯長度的區段如 Stack/Data，易產生外部碎裂）。</li><li><strong>Paging</strong>：分頁機制（將實體記憶體切成固定大小的 Frames，邏輯記憶體切成 Pages，徹底消滅外部碎裂，但會產生內部碎裂）。</li><li><strong>Page Table Entries (PTEs)</strong>：分頁表條目（包含實體頁框編號 PFN，以及 Modify 髒位元、Reference 參照位元、Valid/Invalid 有效無效位元等狀態標記）。</li><li><strong>Reentrant Code / Shared Pages</strong>：可重入程式碼 / 共享分頁（執行期間不變的唯讀程式碼，讓多個行程安全共用同一實體記憶體分頁以節省龐大空間）。</li><li><strong>Hierarchical Paging</strong>：階層式分頁 / 前向映射分頁表（將龐大的分頁表本身再度進行分頁切割，以解決分頁表佔用過多連續主記憶體的問題）。</li></ul><h4 id="六、-效能評估指標-performance-metrics" tabindex="-1">六、 效能評估指標 (Performance Metrics) <a class="header-anchor" href="#六、-效能評估指標-performance-metrics" aria-label="Permalink to &quot;六、 效能評估指標 (Performance Metrics)&quot;">​</a></h4><ul><li><strong>Memory Stall</strong>：記憶體停頓（CPU 因等待較慢的主記憶體傳輸資料而產生的閒置週期）。</li><li><strong>Hit ratio</strong>：命中率（TLB 能成功找對位址映射資料的機率）。</li><li><strong>EAT (Effective Memory-Access Time)</strong>：有效記憶體存取時間（將 TLB 命中與未命中的狀況，考量 TLB 搜尋時間與記憶體查表時間後，依機率進行加權平均的真實效能指標）。</li></ul>',39)])])}const m=r(a,[["render",n]]);export{u as __pageData,m as default};
